 'use strict';
const templates={readonly:{name:'只读',actions:['QUERY','DEFINITION'],description:'查询数据；按资源适用范围查看视图定义'},readwrite:{name:'读写',actions:['QUERY','WRITE','DEFINITION'],description:'查询及新增、更新、删除数据，不包含DDL'},admin:{name:'数据管理员',actions:['QUERY','WRITE','CREATE','ALTER','DROP','DEFINITION'],description:'数据维护及底层可授予的对象管理，不包含Grant或超级用户'}};
const sources={
 mysql:{label:'业务数据库',engine:'MySQL 8.0',namespaces:['sales','crm','finance'],host:'mysql-demo:3306',collector:'odw_collector',manager:'odw_permission_admin'},
 postgresql:{label:'分析数据库',engine:'PostgreSQL 16',namespaces:['public','crm','finance'],host:'pg-demo:5432 / analytics',collector:'odw_collector',manager:'odw_permission_admin'},
 doris:{label:'数仓集群',engine:'Doris',namespaces:['sales_dw','crm_dw','finance_dw'],host:'doris-demo:9030',collector:'odw_collector',manager:'odw_permission_admin'}
};
const roles=[
 {id:'sales',name:'销售分析员',description:'销售库日常分析',native:'odw_sales_8c31',template:'readonly',scopeIndex:0},
 {id:'customer',name:'客户分析员',description:'客户库日常分析',native:'odw_customer_529a',template:'readonly',scopeIndex:1},
 {id:'finance',name:'财务维护员',description:'财务库查询及数据维护',native:'odw_finance_92bd',template:'readwrite',scopeIndex:2},
 {id:'agent',name:'问数助手',description:'智能问数只读角色',native:'odw_agent_5b72',template:'readonly',scopeIndex:0}
];
const members=[{id:'zhang',name:'张明',type:'用户'},{id:'li',name:'李悦',type:'用户'},{id:'wang',name:'王宁',type:'用户'},{id:'retail',name:'零售问数助手',type:'智能体'}];
const tables=[['orders','销售订单明细'],['customers','客户基本信息'],['products','商品信息'],['order_items','订单商品关联'],['payments','支付流水'],['stores','门店信息']];
const state={page:'principals',memberFilter:'all',role:'sales',engine:'doris',namespace:null,subtab:'permissions',resourceType:'SCHEMA',search:'',ref:'metabase',matrices:{},bindings:{},busy:false,records:[{id:'AUTH-DEMO-002',role:'财务维护员',source:'数仓集群',resource:'internal.finance_dw.payments',action:'Load_priv',status:'PARTIAL',time:'2026-10-30 10:14:28'},{id:'AUTH-DEMO-001',role:'销售分析员',source:'数仓集群',resource:'internal.sales_dw.*',action:'Select_priv',status:'SUCCEEDED',time:'2026-10-30 09:32:16'}]};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const role=()=>roles.find(r=>r.id===state.role);
const ns=(engine=state.engine)=>engine===state.engine&&state.namespace?sources[engine].namespaces.includes(state.namespace)?state.namespace:sources[engine].namespaces[0]:sources[engine].namespaces[0];
function binding(memberId,engine=state.engine){const key=engine+'|'+memberId;const accounts={zhang:'odw_zhangming',li:'odw_liyue',retail:'odw_agent_retail'};if(!state.bindings[key])state.bindings[key]={roles:memberId==='zhang'?['sales','customer','finance']:memberId==='li'?['sales','customer']:memberId==='retail'?['agent']:[],username:accounts[memberId]||'',configured:!!accounts[memberId]};return state.bindings[key]}
members.forEach(m=>{if(m.type==='用户'){m.username=({zhang:'zhangming',li:'liyue',wang:'wangning'})[m.id];m.enabled=true}});
const memberRoles=(id,engine=state.engine)=>binding(id,engine).roles.map(rid=>roles.find(r=>r.id===rid)).filter(Boolean);
const countMembers=rid=>members.filter(m=>binding(m.id).roles.includes(rid)).length;
const businessActions=[['ACCESS','访问 Schema'],['QUERY','查询数据'],['WRITE','写入数据'],['CREATE','创建对象'],['ALTER','修改结构'],['DROP','删除对象'],['DEFINITION','查看视图定义']];
const resourceLabels={SCHEMA:'Schema / 数据库',TABLE:'表',VIEW:'视图'};
function resources(type=state.resourceType,engine=state.engine,namespace=ns(engine)){
 if(type==='SCHEMA')return [[namespace,engine==='postgresql'?'访问与创建；不自动授予子表权限':'原生库级范围，包含当前及未来对象']];
 if(type==='VIEW')return [['v_orders_public',engine==='doris'?'逻辑视图 · 不支持写入':'可更新视图 · 仍需满足原生条件'],['v_order_summary','聚合视图 · 本示例只读']];
 return tables;
}
function actionSpec(key,type=state.resourceType,engine=state.engine,name=''){
  const maps={
    doris:{SCHEMA:{QUERY:['Select_priv'],WRITE:['Load_priv'],CREATE:['Create_priv'],ALTER:['Alter_priv'],DROP:['Drop_priv'],DEFINITION:['Show_view_priv']},TABLE:{QUERY:['Select_priv'],WRITE:['Load_priv'],ALTER:['Alter_priv'],DROP:['Drop_priv']},VIEW:{QUERY:['Select_priv'],ALTER:['Alter_priv'],DROP:['Drop_priv'],DEFINITION:['Show_view_priv']}},
    postgresql:{SCHEMA:{ACCESS:['USAGE'],CREATE:['CREATE'],ALTER:'OWNER',DROP:'OWNER'},TABLE:{QUERY:['SELECT'],WRITE:['INSERT','UPDATE','DELETE'],ALTER:'OWNER',DROP:'OWNER'},VIEW:{QUERY:['SELECT'],WRITE:['INSERT','UPDATE','DELETE'],ALTER:'OWNER',DROP:'OWNER',DEFINITION:'VISIBLE'}},
    mysql:{SCHEMA:{QUERY:['SELECT'],WRITE:['INSERT','UPDATE','DELETE'],CREATE:['CREATE','CREATE VIEW'],ALTER:['ALTER'],DROP:['DROP'],DEFINITION:['SHOW VIEW']},TABLE:{QUERY:['SELECT'],WRITE:['INSERT','UPDATE','DELETE'],ALTER:['ALTER'],DROP:['DROP']},VIEW:{QUERY:['SELECT'],WRITE:['INSERT','UPDATE','DELETE'],ALTER:'PARENT',DROP:['DROP'],DEFINITION:['SHOW VIEW']}}
  };
  const value=maps[engine][type][key];
  if(value==='OWNER')return {native:[],mode:'OWNER',reason:'由对象所有权控制；不是可独立GRANT的ALTER／DROP，本原型不转移所有权'};
  if(value==='VISIBLE')return {native:[],mode:'VISIBLE',reason:'PG没有独立SHOW VIEW授权；按原生元数据可见性和平台资源权限展示'};
  if(value==='PARENT')return {native:[],mode:'PARENT',reason:'MySQL修改视图涉及CREATE VIEW及DROP等前提，须分别预览确认，不伪装成单一ALTER授权'};
  if(key==='WRITE'&&type==='VIEW'&&name==='v_order_summary')return {native:[],mode:'UNSUPPORTED',reason:'本示例聚合视图不可更新；不因授予DML就声称可写'};
  if(!value)return {native:[],mode:'UNSUPPORTED',reason:key==='CREATE'?'在Schema／数据库层授予创建新对象能力':type==='SCHEMA'&&engine==='postgresql'?'PG Schema的USAGE／CREATE不等于子表读写，请到表／视图页授权':type==='VIEW'&&key==='WRITE'?'Doris逻辑视图不支持DML写入':'该资源没有此独立授权动作'};
  return {native:value,mode:'GRANT',reason:''};
}

function columns(){return businessActions.filter(([key])=>resources().some(([name])=>['GRANT','OWNER','PARENT','VISIBLE'].includes(actionSpec(key,state.resourceType,state.engine,name).mode)))}
function shortActions(actions){const names={SELECT:'查询',Select_priv:'查询',INSERT:'写入',UPDATE:'写入',DELETE:'写入',Load_priv:'写入',CREATE:'创建对象','CREATE VIEW':'创建对象',Create_priv:'创建对象',ALTER:'修改结构',Alter_priv:'修改结构',DROP:'删除对象',Drop_priv:'删除对象','SHOW VIEW':'查看定义',Show_view_priv:'查看定义',USAGE:'访问Schema',CONNECT:'连接',TRUNCATE:'清空数据',REFERENCES:'引用',TRIGGER:'触发器',INDEX:'索引'};return [...new Set([...actions].map(a=>names[a]||a))].join('、')}
function roleSummary(rid,engine=state.engine){const scopes=[];for(const namespace of sources[engine].namespaces){const actions=new Set();for(const type of ['SCHEMA','TABLE','VIEW'])Object.values(matrix(rid,engine,type,namespace).base).flat().forEach(a=>actions.add(a));if(actions.size)scopes.push(namespace+' · '+shortActions(actions))}return scopes.join('；')||'尚未配置权限'}
function fieldError(message,id){const error=$('#form-error');if(error){error.hidden=false;error.textContent=message}if(id)$('#'+id)?.focus()}
function matrix(rid=state.role,engine=state.engine,type=state.resourceType,namespace=ns(engine)){
 const key=[rid,engine,type,namespace].join('|');
 if(!state.matrices[key]){
  const r=roles.find(r=>r.id===rid),base={},active=r.scopeIndex===sources[engine].namespaces.indexOf(namespace),read=engine==='doris'?'Select_priv':'SELECT';
  resources(type,engine,namespace).forEach(([name],i)=>{
   let grants=[];
   if(active){
    if(type==='SCHEMA')grants=engine==='postgresql'?['USAGE']:[read,...(r.template==='readwrite'?actionSpec('WRITE',type,engine,name).native:[])];
    else if(engine==='postgresql'&&i<3)grants=[read,...(r.template==='readwrite'?actionSpec('WRITE',type,engine,name).native:[])];
   }
   base[name]=grants;
  });
  state.matrices[key]={base:structuredClone(base),draft:structuredClone(base)};
 }
 return state.matrices[key];
}
function inheritedActions(engine,type){return type==='SCHEMA'||engine==='postgresql'?[]:matrix(state.role,engine,'SCHEMA',ns(engine)).base[ns(engine)]||[]}
function markMixed(){document.querySelectorAll('input[data-mixed="true"]').forEach(e=>e.indeterminate=true)}
function agentAssigned(rid=state.role,engine=state.engine){return members.some(m=>m.type==='智能体'&&binding(m.id,engine).roles.includes(rid))}
function hasWriteAccess(rid,engine=state.engine){return sources[engine].namespaces.some(namespace=>['SCHEMA','TABLE','VIEW'].some(type=>{const m=matrix(rid,engine,type,namespace);return Object.values(m.draft).flat().some(a=>!['SELECT','Select_priv','USAGE','CONNECT','SHOW VIEW','Show_view_priv'].includes(a))}))}
function setBusiness(name,key,checked){const spec=actionSpec(key,state.resourceType,state.engine,name);if(spec.mode!=='GRANT'||agentAssigned()&&!['QUERY','ACCESS','DEFINITION'].includes(key))return;const m=matrix();m.draft[name]=checked?[...new Set([...m.draft[name],...spec.native])]:m.draft[name].filter(a=>!spec.native.includes(a))}
function deltas(){const out=[];Object.entries(state.matrices).forEach(([key,m])=>{const[rid,engine,type,namespace]=key.split('|');if(rid!==state.role)return;Object.keys(m.base).forEach(name=>new Set([...m.base[name],...m.draft[name]]).forEach(action=>{const before=m.base[name].includes(action),after=m.draft[name].includes(action);if(before!==after)out.push({engine,resourceType:type,namespace,table:name,action,add:after})}))});return out}
function scopePath(engine,type,name,namespace=ns(engine)){if(type==='SCHEMA')return engine==='postgresql'?namespace:(engine==='doris'?'internal.':'')+namespace+'.*';return(engine==='doris'?'internal.':'')+namespace+'.'+name}
function badge(text,type=''){return `<span class="badge ${type}">${text}</span>`}
function notice(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#toast').hidden=true,3200)}
function sourceSelect(id='member-source'){return `<label class="source-select">数据源 <select id="${id}" aria-label="${id==='member-source'?'成员数据源':'数据源'}">${Object.entries(sources).map(([k,v])=>`<option value="${k}" ${k===state.engine?'selected':''}>${v.label} · ${v.engine}</option>`).join('')}</select></label>`}
function render(){
 document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('selected',b.dataset.page==='principals'&&!!b.closest('aside')&&['principals','roles','records'].includes(state.page));if(b.matches('[role=tab]'))b.setAttribute('aria-selected',String(b.dataset.page===state.page))});
 document.querySelector('aside [data-action="source-management"]').classList.toggle('selected',state.page==='sources');
 document.querySelector('aside [data-page="users"]').classList.toggle('selected',state.page==='users');
 $('#page-title').textContent=state.page==='references'?'界面参考':state.page==='sources'?'数据源':state.page==='users'?'用户管理':'数据权限';
 $('#page-context').innerHTML=['sources','references','users'].includes(state.page)?'':sourceSelect('global-source');
 $('.page-tabs').hidden=['sources','references','users'].includes(state.page);
 $('#content').innerHTML=({roles:renderRoles,principals:renderPrincipals,users:renderUsers,sources:renderSources,records:renderRecords,references:renderReferences}[state.page])();
 if(state.page==='references')attachImageFallback();if(state.page==='principals')filterPrincipals();markMixed();
}
function renderRoles(){matrix();return `<div class="role-layout"><aside class="role-list"><div class="role-list-head"><span>${roles.length} 个角色</span><button class="text-button" data-action="new-role">新建角色</button></div><input aria-label="搜索角色" placeholder="搜索角色" id="role-search">${roles.map(r=>`<button class="role-item ${state.role===r.id?'active':''}" data-role="${r.id}"><strong>${esc(r.name)}</strong><small>${countMembers(r.id)} 位成员${r.staged?' · 待授权':''}</small></button>`).join('')}</aside><section class="role-main"><div class="role-title-row"><div><h2>${esc(role().name)}</h2><p class="role-meta">${esc(role().description)}</p></div><button data-action="member-info">管理成员 · ${countMembers(state.role)}</button></div>${permissionPanel()}</section></div>`}
function roleTags(id){return `<div class="simple-tags">${memberRoles(id).map(r=>`<span class="simple-tag">${esc(r.name)}</span>`).join('')||'<span class="muted">未分配</span>'}</div>`}
function renderPrincipals(){const rows=members.filter(m=>{const b=binding(m.id);return b.roles.length||b.configured});return `<div class="content-pad"><div class="list-toolbar"><div class="filter-controls"><input type="search" id="principal-search" aria-label="搜索成员" placeholder="搜索成员、数据库账号"><select id="member-role-filter" aria-label="按角色筛选"><option value="all">全部角色</option>${roles.map(r=>`<option value="${r.id}" ${state.memberFilter===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select id="member-status-filter" aria-label="按状态筛选"><option value="all">全部状态</option><option value="ready">正常</option><option value="pending">待配置</option><option value="disabled">已停用</option></select></div><button class="primary" data-action="add-member">授权用户</button></div><div class="table-scroll"><table class="member-table"><thead><tr><th>成员</th><th>角色</th><th>数据库账号</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(m=>{const b=binding(m.id),ready=b.roles.length&&b.configured;return `<tr data-principal-row data-member-id="${m.id}" data-status="${m.enabled===false?'disabled':ready?'ready':'pending'}"><td><span class="member-name">${m.name}</span>${m.type==='智能体'?'<span class="type-label">智能体</span>':''}</td><td>${roleTags(m.id)}</td><td><button class="text-button account-link ${b.configured?'':'unbound'}" data-account="${m.id}" title="绑定或修改数据库账号">${esc(b.username)||'绑定账号'}</button></td><td>${badge(m.enabled===false?'已停用':ready?'正常':b.roles.length?'待绑定账号':'待分配角色',m.enabled===false?'red':ready?'':'amber')}</td><td class="row-actions"><button class="text-button" data-member="${m.id}">分配角色</button><button class="text-button" data-effective="${m.id}">权限</button></td></tr>`}).join('')}<tr id="members-empty" hidden><td colspan="5" class="empty">没有匹配的成员，请调整筛选条件。</td></tr></tbody></table></div><div class="table-footer"><span id="member-count">共 ${rows.length} 位成员</span></div></div>`}
function renderSources(){return `<div class="content-pad"><div class="list-toolbar"><span class="muted">${Object.keys(sources).length} 个数据源</span></div><div class="table-scroll"><table><thead><tr><th>数据源</th><th>类型</th><th>采集账号</th><th>授权管理账号</th><th>操作</th></tr></thead><tbody>${Object.entries(sources).map(([k,v])=>`<tr><td>${v.label}</td><td>${v.engine}</td><td>${v.collector}</td><td>${v.manager}</td><td class="row-actions"><button class="text-button" data-source-detail="${k}">配置</button><button class="text-button" data-source-members="${k}">成员权限</button></td></tr>`).join('')}</tbody></table></div></div>`}
function showMember(id='wang',mode='roles'){
 const m=members.find(v=>v.id===id);if(!m)return;
 state.memberEdit={id,engine:state.engine,mode,selected:[...binding(id).roles],username:binding(id).username,configured:binding(id).configured};renderMemberDialog();
}
function accountFields(edit){return `<div class="form-grid"><label class="field full"><span>数据库账号</span><input id="member-username" aria-label="数据库账号" value="${esc(edit.username)}" autocomplete="off" placeholder="输入数据库账号"></label><label class="field full"><span>密码</span><input id="member-password" aria-label="数据库密码" type="password" autocomplete="new-password" placeholder="${edit.configured?'留空保留原密码':'输入数据库密码'}"></label></div>`}
function renderMemberDialog(){const e=state.memberEdit,m=members.find(v=>v.id===e.id),account=e.mode==='account';
 const options=`<div class="role-picker" aria-label="可分配角色">${roles.map(r=>{const blocked=m.type==='智能体'&&hasWriteAccess(r.id,e.engine);return `<label class="role-option ${blocked?'disabled':''}"><input type="checkbox" data-member-role="${r.id}" aria-label="分配 ${r.name}" ${e.selected.includes(r.id)?'checked':''} ${blocked?'disabled':''}><span><strong>${esc(r.name)}</strong><small>${blocked?'智能体仅可分配只读角色':esc(roleSummary(r.id,e.engine))}</small></span></label>`}).join('')}</div><div id="selected-count" class="picker-count">已选 ${e.selected.length} 个角色</div>`;
 modal(account?'绑定数据库账号':'分配角色',`<div class="form-context"><strong>${m.name}</strong><span>${sources[e.engine].label}</span></div>${account?accountFields(e):'<span class="field-label">角色</span>'+options}<p id="form-error" role="alert" class="form-error" hidden></p>`,`<button data-action="close">取消</button><button class="primary" data-action="save-member">保存</button>`);$('#dialog').classList.add('compact-dialog');
}
function userFields(user=null){return `<div class="form-grid"><label class="field full"><span>用户名</span><input id="platform-username" aria-label="平台用户名" value="${esc(user?.username||'')}" ${user?'readonly':''} autocomplete="off" placeholder="用于登录平台"></label><label class="field full"><span>姓名</span><input id="platform-name" aria-label="姓名" value="${esc(user?.name||'')}" placeholder="输入姓名"></label>${user?`<label class="enabled-field full"><input id="platform-enabled" type="checkbox" ${user.enabled!==false?'checked':''}>启用用户</label>`:'<label class="field full"><span>初始登录密码</span><input id="platform-password" aria-label="初始登录密码" type="password" autocomplete="new-password" placeholder="至少8位"></label>'}</div>`}
function readNewUser(){const username=$('#platform-username').value.trim(),name=$('#platform-name').value.trim(),password=$('#platform-password').value;if(!username){fieldError('请输入平台用户名','platform-username');return null}if(members.some(m=>m.type==='用户'&&m.username?.toLowerCase()===username.toLowerCase())){fieldError('用户名已存在，请使用其他用户名','platform-username');return null}if(!name){fieldError('请输入姓名','platform-name');return null}if(password.length<8){fieldError('初始登录密码至少8位','platform-password');return null}return {id:'user'+members.length,name,username,type:'用户',enabled:true}}
function renderUsers(){return `<div class="content-pad"><div class="list-toolbar"><input id="user-search" type="search" aria-label="搜索用户" placeholder="搜索用户名、姓名"><button class="primary" data-action="new-user">新增用户</button></div><div class="table-scroll"><table><thead><tr><th>用户名</th><th>姓名</th><th>登录方式</th><th>状态</th><th>操作</th></tr></thead><tbody>${members.filter(m=>m.type==='用户').map(m=>`<tr data-platform-user><td>${esc(m.username)}</td><td>${esc(m.name)}</td><td>本地账号</td><td>${badge(m.enabled===false?'已停用':'正常',m.enabled===false?'red':'')}</td><td><button class="text-button" data-user-edit="${m.id}">编辑</button></td></tr>`).join('')}<tr id="user-empty" hidden><td colspan="5" class="empty">没有匹配的用户</td></tr></tbody></table></div><div class="table-footer"><span id="user-count">共 ${members.filter(m=>m.type==='用户').length} 位用户</span></div></div>`}
function showUser(userId=null){state.userEdit=userId;const user=userId?members.find(m=>m.id===userId):null;modal(user?'编辑用户':'新增用户',`${userFields(user)}<p id="form-error" role="alert" class="form-error" hidden></p>`,`<button data-action="close">取消</button><button class="primary" data-action="save-user">${user?'保存':'创建用户'}</button>`);$('#dialog').classList.add('compact-dialog')}
function saveUser(){if(state.userEdit){const m=members.find(m=>m.id===state.userEdit),name=$('#platform-name').value.trim();if(!name){fieldError('请输入姓名','platform-name');return}m.name=name;m.enabled=$('#platform-enabled').checked}else{const m=readNewUser();if(!m)return;members.push(m)}close();render();notice('用户资料已保存')}
function showUserAccess(mode='existing'){state.accessEdit={mode,selected:[],engine:state.engine,userId:'',draft:{}};renderUserAccess()}
function renderUserAccess(){const e=state.accessEdit,candidates=members.filter(m=>m.type==='用户'&&m.enabled!==false&&!binding(m.id,e.engine).roles.length);const userField=e.mode==='new'?userFields():`<label class="field"><span>用户</span><select id="access-user" aria-label="选择已有用户"><option value="">请选择平台用户</option>${candidates.map(m=>`<option value="${m.id}" ${e.userId===m.id?'selected':''}>${esc(m.name)}（${esc(m.username)}）</option>`).join('')}</select></label>`;
 modal('授权用户',`<div class="form-context"><span>${sources[e.engine].label}</span></div><div class="access-mode" role="group" aria-label="用户来源"><label><input type="radio" name="access-mode" value="existing" ${e.mode==='existing'?'checked':''}>已有用户</label><label><input type="radio" name="access-mode" value="new" ${e.mode==='new'?'checked':''}>新建用户</label></div>${userField}<div class="access-role-field"><span class="field-label">分配角色</span><div class="role-picker">${roles.map(r=>`<label class="role-option"><input type="checkbox" data-access-role="${r.id}" aria-label="授权 ${r.name}" ${e.selected.includes(r.id)?'checked':''}><span><strong>${esc(r.name)}</strong></span></label>`).join('')}</div></div><p id="form-error" role="alert" class="form-error" hidden></p>`,`<button data-action="close">取消</button><button class="primary" data-action="save-access">${e.mode==='new'?'创建并授权':'确认授权'}</button>`);$('#dialog').classList.add('compact-dialog')}
function saveAccess(){const e=state.accessEdit;let user;if(e.mode==='new'){user=readNewUser();if(!user)return}else{user=members.find(m=>m.id===$('#access-user').value);if(!user){fieldError('请选择平台用户','access-user');return}}if(!e.selected.length){fieldError('请至少选择一个角色');return}if(user.enabled===false){fieldError('用户已停用，请先在用户管理中启用');return}if(e.mode==='new')members.push(user);binding(user.id,e.engine).roles=[...e.selected];state.memberFilter='all';close();render();notice(e.mode==='new'?'用户已创建并授权':'用户授权已保存')}
function saveMember(){const e=state.memberEdit,m=members.find(v=>v.id===e.id),b=binding(e.id,e.engine),withAccount=e.mode==='account';
 const username=withAccount?$('#member-username').value.trim():b.username,password=withAccount?$('#member-password').value:'';
 if(withAccount&&!username){fieldError('请输入数据库账号','member-username');return}
 if(withAccount&&!password&&(!b.configured||username!==b.username)){fieldError('首次绑定或更换账号时，请输入密码','member-password');return}
 if(m.type==='智能体'&&e.selected.some(id=>hasWriteAccess(id,e.engine))){fieldError('智能体只能分配只读角色');return}
 if(withAccount&&members.some(other=>other.id!==m.id&&binding(other.id,e.engine).username===username)){fieldError('此账号已绑定其他成员，请使用独立账号','member-username');return}
 if(e.mode!=='account')b.roles=[...e.selected];
 if(withAccount){b.username=username;b.configured=true}
 close();render();notice(e.mode==='account'?'账号已保存':'角色分配已保存');
}

function effectiveRows(id,engine=state.engine){
 const map=new Map();
 for(const r of memberRoles(id,engine))for(const namespace of sources[engine].namespaces)for(const type of ['SCHEMA','TABLE','VIEW']){
  const m=matrix(r.id,engine,type,namespace);
  for(const[name,actions]of Object.entries(m.base))if(actions.length){const path=scopePath(engine,type,name,namespace),key=type+'|'+path;if(!map.has(key))map.set(key,{path,type,actions:new Set(),roles:new Set()});const entry=map.get(key);actions.forEach(a=>entry.actions.add(a));entry.roles.add(r.name)}
 }
 return [...map.values()];
}
function showEffective(id){const m=members.find(v=>v.id===id),b=binding(id),rows=effectiveRows(id);modal(m.name+'的权限',`<div class="form-context"><span>${sources[state.engine].label}</span><span>账号：${esc(b.username)||'未绑定'}</span></div><div class="permission-summary">${roleTags(id)}</div>${m.enabled===false?'<p class="state-note scope-warning">用户已停用，无法访问平台。</p>':''}${!b.configured?'<p class="state-note scope-warning">请先绑定账号，绑定前无法查询数据。</p>':''}<div class="table-scroll"><table><thead><tr><th>资源范围</th><th>权限</th><th>来源角色</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="code">${row.path}</td><td>${shortActions(row.actions)}</td><td>${[...row.roles].map(esc).join('、')}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">尚未分配资源权限</td></tr>'}</tbody></table></div><details class="advanced-details"><summary>查看数据库权限</summary><pre class="native-sql">${esc(rows.map(row=>row.path+'  '+[...row.actions].join(', ')).join('\n'))}</pre></details>`,`<button data-action="close">关闭</button><button class="primary" data-member="${id}">分配角色</button>`)}
function showNewRole(){modal('新建角色',`<div class="form-grid"><label class="field full"><span>角色名称</span><input id="new-role-name" aria-label="角色名称" placeholder="例如：销售分析员"></label><label class="field full"><span>权限模板</span><select id="role-template" aria-label="权限模板">${Object.entries(templates).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select><small id="template-description">${templates.readonly.description}</small></label><label class="field"><span>${state.engine==='postgresql'?'Schema':'数据库'}</span><select id="template-namespace" aria-label="模板资源范围">${sources[state.engine].namespaces.map(n=>`<option ${n===ns()?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>授权范围</span><select id="template-resource" aria-label="模板资源层级"><option value="TABLE">当前表</option><option value="VIEW">当前视图</option><option value="SCHEMA">整个${state.engine==='postgresql'?'Schema':'数据库'}</option></select></label></div><p class="form-hint">创建后可调整具体权限，确认保存后生效。</p><p id="form-error" role="alert" class="form-error" hidden></p>`,`<button data-action="close">取消</button><button class="primary" data-action="create-role">创建</button>`);$('#dialog').classList.add('compact-dialog')}
function createRole(){
 const name=$('#new-role-name').value.trim();if(!name){fieldError('请输入角色名称','new-role-name');return}if(roles.some(r=>r.name===name)){fieldError('角色名称已存在，请使用其他名称','new-role-name');return}
 const template=$('#role-template').value,engine=state.engine,namespace=$('#template-namespace').value,type=$('#template-resource').value;
 const id='custom'+roles.length;roles.push({id,name,description:namespace+' · '+templates[template].name+'权限',native:'odw_role_'+id,template,scopeIndex:-1,staged:true});
 state.role=id;state.engine=engine;state.namespace=namespace;state.resourceType=type;state.page='roles';state.subtab='permissions';state.search='';
 const m=matrix();resources().forEach(([n])=>{let keys=[...templates[template].actions];if(engine==='postgresql'&&type==='SCHEMA')keys.push('ACCESS');m.draft[n]=[...new Set(keys.flatMap(key=>actionSpec(key,type,engine,n).native))]});
 if(engine==='postgresql'&&type!=='SCHEMA')matrix(id,engine,'SCHEMA',namespace).draft[namespace]=['USAGE'];
 close();render();notice('角色已创建，请确认资源权限');
}
function showSource(engine){state.engine=engine;state.namespace=null;const src=sources[engine];modal(src.label+' · 连接职责',`<div class="source-detail-strip"><div><small>类型</small>${src.engine}</div><div><small>连接</small><span class="code">${src.host}</span></div></div><label class="field"><span>元数据采集账号</span><input value="${src.collector}" readonly></label><label class="field"><span>授权管理账号</span><input value="${src.manager}" readonly></label><p class="notice-line">角色映射原生权限集合；成员在接入时绑定登录账号。这里不维护每位成员的账号。</p>`,`<button data-action="source-members">到成员管理</button><button class="primary" data-action="close">完成</button>`,true)}
function statusBadge(status){return({SUCCEEDED:badge('已生效'),PARTIAL:badge('部分成功','amber'),FAILED:badge('失败','red'),UNKNOWN:badge('待核对','amber')})[status]||badge('执行中','blue')}
function recordTable(records){return `<div class="table-scroll"><table><thead><tr><th>操作编号 / 时间</th><th>角色 / 数据源</th><th>变更内容</th><th>结果</th><th>操作</th></tr></thead><tbody>${records.map(r=>`<tr><td class="code">${r.id}<span class="table-comment">${r.time}</span></td><td>${esc(r.role)}<span class="table-comment">${r.source}</span></td><td>${esc(r.resource)}<span class="table-comment">${esc(r.action)}</span></td><td>${statusBadge(r.status)}</td><td><button class="text-button" data-record="${r.id}">查看步骤</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无操作记录</td></tr>'}</tbody></table></div>`}
function renderRecords(){return `<div class="content-pad"><div class="section-heading"><div><h2>授权记录</h2><p class="muted small">即时授权、原生回读和平台保存结果</p></div></div>${recordTable(state.records)}</div>`}
function sqlFor(d){const target=d.engine==='doris'?`ROLE '${role().native}'`:d.engine==='mysql'?`'${role().native}'`:role().native,obj=d.engine==='postgresql'?(d.resourceType==='SCHEMA'?`SCHEMA "${d.namespace}"`:`TABLE "${d.namespace}"."${d.table}"`):(d.engine==='doris'?'`internal`.':'')+'`'+d.namespace+'`.'+(d.resourceType==='SCHEMA'?'*':'`'+d.table+'`');return `${d.add?'GRANT':'REVOKE'} ${d.action} ON ${obj} ${d.add?'TO':'FROM'} ${target};`}
function showPreview(){const ds=deltas();if(!ds.length){notice('没有待确认的权限变更');return}state.preview=structuredClone(ds);modal('确认权限变更',`<div class="dialog-summary"><div><h2>${esc(role().name)}</h2><p>影响 ${countMembers(state.role)} 位成员</p></div>${badge('立即生效','blue')}</div><div class="table-scroll"><table><thead><tr><th>变化</th><th>资源范围</th><th>数据库权限</th></tr></thead><tbody>${ds.map(d=>`<tr><td class="${d.add?'delta-add':'delta-remove'}">${d.add?'授予':'撤销'}</td><td>${sources[d.engine].label}<span class="table-comment code">${scopePath(d.engine,d.resourceType,d.table,d.namespace)}</span></td><td class="code">${d.action}</td></tr>`).join('')}</tbody></table></div>${ds.some(d=>d.resourceType==='SCHEMA'&&d.engine!=='postgresql')?'<p class="state-note scope-warning">原生库级范围包含当前及未来对象；库级删除／修改结构还可能影响数据库本身。</p>':''}${ds.some(d=>d.engine==='postgresql'&&d.action==='INSERT'&&d.table==='orders')?'<p class="notice-line">示例orders.id使用SERIAL；实际还需核实其依赖序列USAGE等权限，不能把表INSERT当作所有前提已具备。</p>':''}<details><summary class="small muted">原生语句示意</summary><pre class="native-sql">${esc(ds.map(sqlFor).join('\n'))}</pre></details><details class="advanced-details"><summary>原型演示选项</summary><div class="demo-controls"><select id="scenario" aria-label="原型执行结果"><option value="success">两边均成功</option><option value="partial">数据源成功，平台保存失败</option><option value="failed">数据源拒绝，未发生变更</option></select></div></details>`,`<button data-action="close">返回修改</button><button class="primary" data-action="execute">确认保存</button>`)}
function showResult(rec){const ok=rec.status==='SUCCEEDED',partial=rec.status==='PARTIAL';modal(ok?'授权已生效':partial?'部分成功，需要核对':'授权失败',`<div class="status-hero"><span class="status-symbol ${ok?'':partial?'amber':'red'}">${ok?'✓':'!'}</span><div><h2>${ok?'原生权限与平台记录均已完成':partial?'数据源已生效，平台记录未完成':'数据库拒绝，本次未更改权限'}</h2><p class="code">${rec.id}</p></div></div><ol class="steps"><li>数据源 GRANT / REVOKE<small>${rec.status==='FAILED'?'已拒绝':'已执行'}</small></li><li>回读权限<small>${rec.status==='FAILED'?'未执行':'结果一致'}</small></li><li>平台记录<small>${ok?'已保存':partial?'保存失败':'未执行'}</small></li></ol>${partial?'<p class="state-note">按操作编号核对实际结果，不自动重放或重授已撤权限；只处理相关账号及角色。</p>':''}`,`<button data-action="close">关闭</button><button class="primary" data-action="view-records">查看授权记录</button>`)}
async function execute(){if(state.busy)return;const outcome=$('#scenario').value;state.busy=true;$('#dialog').innerHTML='<div class="dialog-body"><h2>正在执行即时授权</h2><p>原型演示，不发送数据库请求…</p></div>';await new Promise(r=>setTimeout(r,400));const ds=state.preview,rec={id:'AUTH-DEMO-'+String(state.records.length+1).padStart(3,'0'),role:role().name,source:[...new Set(ds.map(d=>sources[d.engine].label))].join('、'),resource:ds.length===1?scopePath(ds[0].engine,ds[0].resourceType,ds[0].table,ds[0].namespace):ds.length+' 项资源动作',action:ds.map(d=>(d.add?'授予 ':'撤销 ')+d.action).join('、'),status:outcome==='success'?'SUCCEEDED':outcome==='partial'?'PARTIAL':'FAILED',time:'2026-10-30 · 原型演示'};state.records.unshift(rec);if(rec.status==='SUCCEEDED'){Object.entries(state.matrices).forEach(([key,m])=>{if(key.startsWith(state.role+'|'))m.base=structuredClone(m.draft)});role().staged=false}state.busy=false;render();showResult(rec)}
function permissionPanel(){const m=matrix(),changes=deltas(),items=resources().filter(([n,c])=>(n+c).toLowerCase().includes(state.search.toLowerCase())),cols=columns();
 return `<div class="permission-toolbar"><div class="resource-tabs" role="group" aria-label="资源类型">${Object.entries(resourceLabels).map(([key,label])=>`<button data-resource-type="${key}" class="${state.resourceType===key?'active':''}" aria-pressed="${state.resourceType===key}">${key==='SCHEMA'?(state.engine==='postgresql'?'Schema':'数据库'):label}</button>`).join('')}</div><button class="text-button" data-action="mapping">权限说明</button></div><div class="list-toolbar resource-filters"><div class="filter-controls"><label class="source-select">${state.engine==='postgresql'?'Schema':'数据库'}<select id="namespace">${sources[state.engine].namespaces.map(n=>`<option ${n===ns()?'selected':''}>${n}</option>`).join('')}</select></label><input type="search" id="table-search" aria-label="搜索资源" placeholder="搜索资源" value="${esc(state.search)}"></div>${state.resourceType==='TABLE'?'<button class="text-button" data-action="batch-query">批量勾选查询权限</button>':''}</div>${state.resourceType==='SCHEMA'?`<p class="scope-note">${state.engine==='postgresql'?'Schema访问与表查询权限分别授权。':'整个数据库授权包含当前及后续新增对象。'}</p>`:''}<div class="table-scroll"><table class="permission-table"><thead><tr><th>资源名称</th>${cols.map(([,label])=>`<th>${label==='查询数据'?'查询':label==='写入数据'?'写入':label==='查看视图定义'?'查看定义':label}</th>`).join('')}<th>操作</th></tr></thead><tbody>${items.map(([name,comment])=>`<tr><td><span class="table-name">${esc(name)}</span><span class="table-comment">${esc(state.resourceType==='SCHEMA'?scopePath(state.engine,state.resourceType,name):comment)}</span></td>${cols.map(([key])=>{const spec=actionSpec(key,state.resourceType,state.engine,name);if(spec.mode!=='GRANT')return `<td><span class="unavailable" title="${esc(spec.reason)}">${spec.mode==='OWNER'?'所有者权限':spec.mode==='VISIBLE'?'随资源可见':spec.mode==='PARENT'?'需前提权限':'—'}</span></td>`;const inherited=inheritedActions(state.engine,state.resourceType),effective=[...new Set([...m.draft[name],...inherited])],some=spec.native.some(a=>effective.includes(a)),all=spec.native.every(a=>effective.includes(a)),parent=spec.native.some(a=>inherited.includes(a)),disabled=parent||agentAssigned()&&!['QUERY','ACCESS','DEFINITION'].includes(key),changed=spec.native.some(a=>m.base[name].includes(a)!==m.draft[name].includes(a));return `<td class="${changed?'pending-cell':''}"><input type="checkbox" data-table="${name}" data-business="${key}" data-mixed="${some&&!all}" aria-label="${name} ${key}" ${all?'checked':''} ${disabled?'disabled':''} title="${esc(parent?'继承数据库级权限，请在上层修改':disabled?'此角色含智能体成员，只允许查询':spec.native.join(' + '))}">${parent?'<span class="inherited-label">继承</span>':''}</td>`}).join('')}<td><button class="text-button" data-refine="${name}">细分</button></td></tr>`).join('')||`<tr><td class="empty" colspan="${cols.length+2}">未找到匹配资源</td></tr>`}</tbody></table></div><div class="table-footer"><span>共 ${items.length} 项资源</span><details class="role-mapping"><summary>数据库角色</summary><code>${role().native}</code></details></div>${changes.length?`<div class="savebar"><span>已修改 <strong>${changes.length}</strong> 项权限</span><div class="buttons"><button data-action="reset">重置</button><button class="primary" data-action="preview">保存权限</button></div></div>`:''}`;
}
const references={metabase:{title:'Metabase · 表权限矩阵',img:'https://cdn.metabase.com/learn/images/guide-to-data-permissions/grant-table-access.webp',url:'https://www.metabase.com/learn/metabase-basics/administration/permissions/data-permissions',date:'官方 Learn 教程截图；非本次登录控制台实拍',borrow:'借鉴按组／数据源切换视角、表级下钻、动作分列，以及提交前确认变更。',difference:'它区分查看数据、创建查询、下载等产品权限；我们的主动作对应数据库原生授权，使用受限账号执行自由 SQL。'},huawei:{title:'华为 DataArts Studio · 数据视角授权',img:'https://support.huaweicloud.com/usermanual-dataartsstudio/zh-cn_image_0000001937488158.png',url:'https://support.huaweicloud.com/usermanual-dataartsstudio/dataartsstudio_01_1157.html',date:'官方《配置角色》图 6；文档更新于 2026-10-13',borrow:'借鉴角色详情拆分数据权限、成员列表、数据源角色配置；从已采集目录选择资源。',difference:'它另有权限集、角色信息与权限同步、细粒度认证等配置；我们的确认请求即时双写，不增加独立同步按钮和队列。'},huaweiRole:{title:'华为 DataArts Studio · 角色详情',img:'https://support.huaweicloud.com/usermanual-dataartsstudio/zh-cn_image_0000002547029585.png',url:'https://support.huaweicloud.com/usermanual-dataartsstudio/dataartsstudio_01_1157.html',date:'官方《配置角色》图 1；文档更新于 2026-10-13',borrow:'借鉴左侧角色导航与右侧角色详情，权限、成员保持在同一角色上下文。',difference:'我们不引入其多层权限集和从属角色，保持平面角色；数据库账号在成员接入时绑定。'},dataworks:{title:'阿里 DataWorks · 数据访问控制',url:'https://help.aliyun.com/zh/dataworks/user-guide/data-access-control/',date:'当前官方文档以文字和表格说明为主，本页不伪造控制台截图',borrow:'借鉴主动授权与权限记录的职责划分，以及各引擎按实际能力提供不同动作。',difference:'它同时覆盖申请、审批等流程；我们先做管理员即时授权，不新增申请单或审批中心。'}};
function renderReferences(){const ref=references[state.ref];return `<div class="content-pad"><div class="section-heading"><div><h2>官方实际界面与我们的差异</h2><p class="muted small">原图直接引用官方文档，点击可放大；不会将重绘图冒充产品截图</p></div><button data-page="roles">返回我们的原型</button></div><div class="ref-tabs">${Object.entries(references).map(([key,v])=>`<button class="${state.ref===key?'active':''}" data-reference="${key}">${({metabase:'Metabase',huawei:'华为 · 数据权限',huaweiRole:'华为 · 角色详情',dataworks:'DataWorks · 文档对照'})[key]}</button>`).join('')}</div><div class="reference-layout"><div>${ref.img?`<a href="${ref.img}" target="_blank" rel="noopener noreferrer"><img class="reference-image" src="${ref.img}" alt="${esc(ref.title)}官方实际截图" referrerpolicy="no-referrer"></a><p id="image-fallback" class="notice-line" hidden>原图暂时无法加载，可从下方官方文档查看；这里不替换为重绘图。</p>`:`<div class="reference-info"><h2>数据访问控制</h2><p>当前官方入口：数据治理 → 安全中心 → 数据平台安全 → 数据访问控制。</p><p>包含权限申请、主动授权、权限审批、记录与审计等职责。各引擎可用能力不同。</p><a href="${ref.url}" target="_blank" rel="noopener noreferrer">打开 DataWorks 当前官方说明 ↗</a><p class="tiny muted">这是说明摘要，不是产品截图。两张可核实的产品 UI 原图请看 Metabase／华为页签。</p></div>`}<div class="reference-caption"><span>${ref.date}</span><a href="${ref.url}" target="_blank" rel="noopener noreferrer">官方来源 ↗</a></div></div><aside class="reference-copy"><div><h3>我们借鉴什么</h3><p>${ref.borrow}</p></div><div><h3>我们如何简化</h3><p>${ref.difference}</p><div class="chips"><span class="chip">平面角色</span><span class="chip">原生鉴权</span><span class="chip">即时授权</span></div></div></aside></div><div class="comparison"><div class="section-heading"><h3>对照重点</h3><span class="small muted">以下为方案取舍，非竞品能力排名</span></div><table><thead><tr><th>维度</th><th>Metabase</th><th>华为 DataArts Studio</th><th>阿里 DataWorks</th><th>OpenDataWorks 本次原型</th></tr></thead><tbody><tr><td>主要对象</td><td>用户组 × 数据源／表</td><td>角色／权限集 × 数据源资源</td><td>引擎资产 × 授权对象</td><td>角色 × 成员 × 原生资源动作</td></tr><tr><td>交互组织</td><td>权限矩阵、逐级下钻</td><td>角色详情，多页签配置</td><td>申请／主动授权／记录等</td><td>角色配置资源，成员分配多角色并绑定账号</td></tr><tr><td>执行方式</td><td>应用权限；另有数据库身份模拟</td><td>支持数据源角色及权限同步</td><td>按引擎授权；支持主动授权入口</td><td>确认后即时 GRANT / REVOKE＋平台保存</td></tr><tr><td>当前取舍</td><td>不照搬其产品权限粒度</td><td>不引入多层权限集／从属角色</td><td>先不引入申请审批流程</td><td>不做后台授权队列或全域待同步门禁</td></tr></tbody></table></div></div>`}
function attachImageFallback(){const image=$('.reference-image');if(image)image.addEventListener('error',()=>{const e=$('#image-fallback');if(e)e.hidden=false})}
let previousFocus;
function modal(title,body,foot='',drawer=false){if($('#overlay').hidden)previousFocus=document.activeElement;$('#dialog').className='dialog'+(drawer?' drawer':'');$('#dialog').innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close-button" data-action="close" aria-label="关闭弹窗">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-foot">${foot||'<button data-action="close">关闭</button>'}</footer>`;$('#overlay').hidden=false;([...$('#dialog').querySelectorAll('input:not([type=radio]):not([type=checkbox]),select')].find(el=>!el.disabled&&!el.readOnly&&el.getClientRects().length)||[...$('#dialog').querySelectorAll('input')].find(el=>!el.disabled&&!el.readOnly&&el.getClientRects().length)||$('#dialog').querySelector('button')).focus()}
function close(){if(state.busy)return;$('#dialog').querySelectorAll('input[type=password]').forEach(el=>el.value='');$('#overlay').hidden=true;if(previousFocus?.isConnected)previousFocus.focus()}
function showFine(name){
  state.fineName=name;const m=matrix(),inherited=inheritedActions(state.engine,state.resourceType);let allowed=[...new Set(columns().flatMap(([k])=>actionSpec(k,state.resourceType,state.engine,name).native))];
  if(state.resourceType==='TABLE'&&state.engine==='postgresql')allowed.push('TRUNCATE','REFERENCES','TRIGGER');
  if(state.resourceType==='TABLE'&&state.engine==='mysql')allowed.push('INDEX','REFERENCES');
  modal('权限细分 · '+name,`<p class="small code">${esc(scopePath(state.engine,state.resourceType,name))}</p><div class="native-options">${allowed.map(a=>{const fromParent=inherited.includes(a),disabled=fromParent||agentAssigned()&&!['SELECT','Select_priv','USAGE','SHOW VIEW','Show_view_priv'].includes(a);return `<label><input type="checkbox" data-native-fine="${a}" ${m.draft[name].includes(a)||fromParent?'checked':''} ${disabled?'disabled':''}> <span class="code">${a}</span>${fromParent?' <span class="muted tiny">来自库级授权</span>':''}</label>`}).join('')}</div>${state.engine==='doris'?'<p class="notice-line">Load_priv不能再分成独立INSERT／UPDATE／DELETE权限。Grant_priv属于授权管理能力，不在普通业务角色中授予。</p>':''}${state.engine==='postgresql'?'<p class="notice-line">ALTER／DROP由对象所有权控制，不能在这里单独GRANT。聚合视图本示例不提供写入动作；没有独立SHOW VIEW权限。</p>':''}`,`<button class="primary" data-action="fine-done">完成</button>`,true);
}
function showMapping(){modal('权限说明',`<p class="small muted">不同数据源支持的权限有所不同，可按需查看或细分。</p><table><thead><tr><th>统一术语</th><th>Doris</th><th>PostgreSQL</th><th>MySQL</th></tr></thead><tbody><tr><td>查询数据</td><td>Select_priv</td><td>表／视图 SELECT</td><td>SELECT</td></tr><tr><td>写入数据</td><td>Load_priv，组合写权限</td><td>INSERT＋UPDATE＋DELETE，可细分</td><td>INSERT＋UPDATE＋DELETE，可细分</td></tr><tr><td>创建对象</td><td>数据库 Create_priv</td><td>Schema CREATE，含创建函数等对象</td><td>库 CREATE／CREATE VIEW</td></tr><tr><td>修改结构</td><td>Alter_priv</td><td>对象所有权控制，不能独立GRANT ALTER</td><td>表ALTER；视图另需CREATE VIEW／DROP前提</td></tr><tr><td>删除对象</td><td>Drop_priv</td><td>对象所有权控制，不能独立GRANT DROP</td><td>DROP，不是DELETE数据</td></tr><tr><td>查看视图定义</td><td>Show_view_priv</td><td>无独立SHOW VIEW授权</td><td>SHOW VIEW</td></tr><tr><td>访问Schema</td><td>没有与PG USAGE等价的库表权限</td><td>USAGE，不等于子表读写</td><td>没有与PG USAGE等价的权限</td></tr><tr><td>授权管理（高级）</td><td>Grant_priv，可能涉及账号／角色管理</td><td>对象GRANT OPTION、角色ADMIN等不同机制</td><td>GRANT OPTION、角色管理等不同机制</td></tr></tbody></table><p class="notice-line">Doris／MySQL库级通配作用域覆盖当前及未来对象；PG Schema USAGE／CREATE不提供子表SELECT。PG当前表批量授权与未来默认权限是另外两件事，不能等价映射。</p><p class="notice-line">普通业务角色不提供授权管理开关；该能力由管理连接单独验证，不把Doris Grant_priv等价成一个通用可转授权标志。</p>`)}
function showLoadGrant(){modal('Load 与 Grant 分别做什么？',`<div class="explain-block"><h3>Load：操作数据</h3><p>Doris的组合写权限，包括数据导入、插入、删除等；具体SQL仍受版本、表模型及其他前提限制。可以将它显示为统一的“写入数据”，不能拆成可分别撤销的假开关。</p><h3>Grant：管理权限</h3><p>允许给别人授予／回收权限，还可能涉及用户和角色管理；分配角色需要全局Grant能力，不能当作普通“写数据”。它放在授权管理账号的能力检查中，不默认授给业务用户。</p><h3>为什么不只写“增删改查”？</h3><p>新增行不等于创建表，更新数据不等于修改表结构，DELETE数据不等于DROP对象。常用界面用统一中文名称，把数据操作和对象结构操作明确分开。</p><a href="https://doris.apache.org/docs/3.x/admin-manual/auth/authentication-and-authorization/" target="_blank" rel="noopener noreferrer">Doris官方权限说明 ↗</a></div>`)}


document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||state.busy)return;
 if(b.dataset.resourceType){state.resourceType=b.dataset.resourceType;state.search='';render();return}
 if(b.dataset.role){state.role=b.dataset.role;state.namespace=sources[state.engine].namespaces[role().scopeIndex]||ns();state.search='';render();return}
 if(b.dataset.userEdit){showUser(b.dataset.userEdit);return}
 if(b.dataset.account){showMember(b.dataset.account,'account');return}
 if(b.dataset.member){showMember(b.dataset.member);return}
 if(b.dataset.effective){showEffective(b.dataset.effective);return}
 if(b.dataset.refine){showFine(b.dataset.refine);return}
 if(b.dataset.reference){state.ref=b.dataset.reference;render();return}
 if(b.dataset.sourceDetail){showSource(b.dataset.sourceDetail);return}
 if(b.dataset.sourceMembers){state.engine=b.dataset.sourceMembers;state.namespace=null;state.memberFilter='all';state.page='principals';render();return}
 if(b.dataset.record){showResult(state.records.find(r=>r.id===b.dataset.record));return}
 if(b.dataset.page){close();state.page=b.dataset.page;render();return}
 const action=b.dataset.action;
 ({close,preview:showPreview,execute,mapping:showMapping,'load-grant':showLoadGrant,'fine-done':()=>{close();render()},'new-role':showNewRole,'create-role':createRole,'add-member':()=>showUserAccess(),'new-user':()=>showUser(),'save-user':saveUser,'save-access':saveAccess,'save-member':saveMember,'member-info':()=>{state.memberFilter=state.role;state.page='principals';render()},'source-management':()=>{state.page='sources';render()},'source-members':()=>{close();state.page='principals';render()},'view-records':()=>{close();state.page='records';render()},references:()=>{state.page='references';render()},reset:()=>{Object.entries(state.matrices).forEach(([k,m])=>{if(k.startsWith(state.role+'|'))m.draft=structuredClone(m.base)});render()},'batch-query':()=>{resources().forEach(([n])=>setBusiness(n,'QUERY',true));render()}})[action]?.();
});
document.addEventListener('change',e=>{const el=e.target;if($('#form-error'))$('#form-error').hidden=true;
 if(el.id==='global-source'){state.engine=el.value;state.namespace=sources[state.engine].namespaces[role().scopeIndex]||null;state.search='';state.memberFilter='all';render()}
 if(el.id==='namespace'){state.namespace=el.value;state.search='';render()}
 if(el.dataset.business){setBusiness(el.dataset.table,el.dataset.business,el.checked);render()}
 if(el.dataset.nativeFine){const a=el.dataset.nativeFine,m=matrix(),name=state.fineName;m.draft[name]=el.checked?[...new Set([...m.draft[name],a])]:m.draft[name].filter(v=>v!==a)}
 if(el.dataset.memberRole){const selected=state.memberEdit.selected;state.memberEdit.selected=el.checked?[...new Set([...selected,el.dataset.memberRole])]:selected.filter(id=>id!==el.dataset.memberRole);$('#selected-count').textContent=`已选 ${state.memberEdit.selected.length} 个角色`}
 if(el.name==='access-mode'){if($('#platform-username'))state.accessEdit.draft={username:$('#platform-username').value,name:$('#platform-name').value};state.accessEdit.mode=el.value;renderUserAccess();if(el.value==='new'){$('#platform-username').value=state.accessEdit.draft.username||'';$('#platform-name').value=state.accessEdit.draft.name||''}}
 if(el.id==='access-user')state.accessEdit.userId=el.value;
 if(el.dataset.accessRole){const selected=state.accessEdit.selected;state.accessEdit.selected=el.checked?[...new Set([...selected,el.dataset.accessRole])]:selected.filter(id=>id!==el.dataset.accessRole)}
 if(el.id==='role-template')$('#template-description').textContent=templates[el.value].description;
 if(el.id==='member-role-filter'){state.memberFilter=el.value;filterPrincipals()}
 if(el.id==='member-status-filter')filterPrincipals();
});
function filterPrincipals(){const q=$('#principal-search').value.trim().toLowerCase(),rid=$('#member-role-filter').value,status=$('#member-status-filter').value;let count=0;document.querySelectorAll('[data-principal-row]').forEach(row=>{const match=row.textContent.toLowerCase().includes(q)&&(rid==='all'||binding(row.dataset.memberId).roles.includes(rid))&&(status==='all'||row.dataset.status===status);row.hidden=!match;if(match)count++});$('#members-empty').hidden=count!==0;$('#member-count').textContent=`共 ${count} 位成员`}
document.addEventListener('input',e=>{if(e.target.id==='table-search'){const start=e.target.selectionStart;state.search=e.target.value;$('.role-main').innerHTML=renderRoles().match(/<section class="role-main">([\s\S]*)<\/section><\/div>$/)[1];markMixed();$('#table-search').focus();$('#table-search').setSelectionRange(start,start)}if(e.target.id==='role-search')document.querySelectorAll('.role-item').forEach(r=>r.hidden=!r.textContent.includes(e.target.value));if(e.target.id==='principal-search')filterPrincipals();if(e.target.id==='user-search'){let count=0;const q=e.target.value.toLowerCase();document.querySelectorAll('[data-platform-user]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q);if(!row.hidden)count++});$('#user-empty').hidden=count>0;$('#user-count').textContent=`共 ${count} 位用户`}if($('#form-error'))$('#form-error').hidden=true});
document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')close();if(e.key==='Tab'){const els=[...$('#dialog').querySelectorAll('button,input,select,a[href],summary')].filter(el=>!el.disabled&&el.getClientRects().length);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const initial=new URLSearchParams(location.search);if(initial.get('page')in{roles:1,principals:1,sources:1,records:1,references:1,users:1})state.page=initial.get('page');if(initial.get('source')in sources)state.engine=initial.get('source');if(initial.get('ref')in references)state.ref=initial.get('ref');if(initial.get('resource')in resourceLabels)state.resourceType=initial.get('resource');if(sources[state.engine].namespaces.includes(initial.get('namespace')))state.namespace=initial.get('namespace');render();
if(initial.get('scene')==='preview'){state.page='roles';state.role='sales';state.namespace=sources[state.engine].namespaces[0];state.resourceType='TABLE';matrix();setBusiness('orders','WRITE',true);render();showPreview()}
if(initial.get('scene')==='partial')showResult(state.records[0]);
if(initial.get('scene')==='member'){state.page='principals';render();showMember('zhang')}
if(initial.get('scene')==='account'){state.page='principals';render();showMember('zhang','account')}
if(initial.get('scene')==='effective'){state.page='principals';render();showEffective('zhang')}
if(initial.get('scene')==='template'){state.page='roles';render();showNewRole()}

if(initial.get('scene')==='add'){state.page='principals';render();showUserAccess(initial.get('mode')==='new'?'new':'existing')}
if(initial.get('scene')==='user'){state.page='users';render();showUser()}
